const snippets={"Python": ["from typing import Optional", "", "class Solution:", "", "    def sortList(self, head: Optional[ListNode]) -> Optional[ListNode]:", "        if head is None or head.next is None:", "            return head", "        (slow, fast) = (head, head.next)", "        while fast and fast.next:", "            slow = slow.next", "            fast = fast.next.next", "        (l1, l2) = (head, slow.next)", "        slow.next = None", "        (l1, l2) = (self.sortList(l1), self.sortList(l2))", "        dummy = ListNode()", "        tail = dummy", "        while l1 and l2:", "            if l1.val <= l2.val:", "                tail.next = l1", "                l1 = l1.next", "            else:", "                tail.next = l2", "                l2 = l2.next", "            tail = tail.next", "        tail.next = l1 or l2", "        return dummy.next"], "Java": ["import java.util.*;", "class Solution {", "    public ListNode sortList(ListNode head) {", "        if (head == null || head.next == null) {", "            return head;", "        }", "        ListNode slow = head, fast = head.next;", "        while (fast != null && fast.next != null) {", "            slow = slow.next;", "            fast = fast.next.next;", "        }", "        ListNode l1 = head, l2 = slow.next;", "        slow.next = null;", "        l1 = sortList(l1);", "        l2 = sortList(l2);", "        ListNode dummy = new ListNode();", "        ListNode tail = dummy;", "        while (l1 != null && l2 != null) {", "            if (l1.val <= l2.val) {", "                tail.next = l1;", "                l1 = l1.next;", "            } else {", "                tail.next = l2;", "                l2 = l2.next;", "            }", "            tail = tail.next;", "        }", "        tail.next = l1 != null ? l1 : l2;", "        return dummy.next;", "    }", "}"]};
